            if (this.logIsInfoEnabled("cacheAllData")) {
                this.logInfo("invalidateCache: invalidating client-side cache", "cacheAllData");
            }

            delete this.cacheData;
            delete this.testData;
            this.cacheLastFetchTime = 0;
