    // +link{DataBoundComponent,DataBoundComponents}, see +link{canvas.autoPopulateData}.
    // @group dataContext
    // @visibility external
    //<

    //> @attr createScreenSettings.clobberDataSources (Boolean : false : IRW)
    // Should DataSources referenced by the screen clobber existing, globally-bound DataSources
