    //> @method dynamicForm.cancel() ([])
    //
    // This method exists for clean integration with existing server frameworks that have a
    // 'cancel' feature which typically clears session state associated with the form.  When
    // this method is called, an RPC is sent to the server.  You must pass the appropriate
    // params property in the request properties as required by your server framework.
    // <P>
    // For example:
    // <smartclient><pre>
    // var requestProperties = {
    //     params: {CANCEL: "cancel"}
    // };
    // </pre></smartclient><smartgwt><pre>
    // DSRequest requestProperties = new DSRequest();
    // Map params = new HashMap();
    // params.put("CANCEL", "cancel");
    // requestProperties.setParams(params);
    // </pre></smartgwt>
    //
    // Note that no other form data is sent.  By default the current top-level page is replaced
    // with the reply.  If you wish to ignore the server reply instead, include the following
    // request properties:
    // <smartclient><pre>
    // var requestProperties = {
    //     // other props ...
    //     ignoreTimeout: true,
    //     target: null
    // };
    // </pre></smartclient><smartgwt><pre>
    // DSRequest requestProperties = new DSRequest();
    // // other request property settings ...
    // requestProperties.setIgnoreTimeout(true);
    // requestProperties.setAttribute("target", null);
    // </pre></smartgwt>
    // @see dynamicForm.cancelEditing()
    // @param requestProperties (DSRequest)  additional properties to set on the RPCRequest
    //                                       that will be issued
    // @deprecated As of Smartclient version 13.0, due to the removal of Apache Struts.
    // @group submitting
    // @visibility external
    //<
    cancel : function (requestProps) {
        var cancelRPC = {
            actionURL: this.action,
            target: window,
            sendNoQueue: true,
            ignoreTimeout: true,
            useXmlHttpRequest: false,
            //params: { }, // set below
            useSimpleHttp: true
        };
        //cancelRPC.params[this.cancelParamName] = this.cancelParamValue;

        //>DEBUG
        if (!cancelRPC.actionURL) {
            this.logWarn("No actionURL defined for the cancel RPC - set 'action' on your form or"
                         + "provide an actionURL in the requestProperties to cancel()");
            return;
        }
        //<DEBUG

        isc.addProperties(cancelRPC, requestProps);

        isc.rpc.sendRequest(cancelRPC);
    },

